import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';
import './App.css';

// Simple check for low-spec device (less than 4GB memory)
const isLowSpecDevice = navigator.deviceMemory && navigator.deviceMemory < 4;

// Custom hook to manage model caching
const useModelCache = () => {
  const [modelCache, setModelCache] = useState({});

  const loadModel = useCallback((modelPath) => {
    return new Promise((resolve, reject) => {
      if (modelCache[modelPath]) {
        resolve(modelCache[modelPath]);
        return;
      }

      const loader = new OBJLoader();
      loader.load(
        modelPath,
        (obj) => {
          setModelCache((prev) => ({ ...prev, [modelPath]: obj }));
          resolve(obj);
        },
        undefined,
        reject
      );
    });
  }, [modelCache]);

  return { loadModel };
};

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);
  const { loadModel } = useModelCache();
  const groupRef = useRef();

  useEffect(() => {
    loadModel(modelPath).then(setModel).catch(console.error);
  }, [modelPath, loadModel]);

  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {model ? <primitive object={model} /> : <mesh><boxGeometry /><meshBasicMaterial wireframe /></mesh>}
    </group>
  );
};

const App = () => {
  const [models, setModels] = useState([]);
  const [selectedModel, setSelectedModel] = useState(null);

  useEffect(() => {
    fetch('./models.json')
      .then((response) => response.json())
      .then((data) => {
        const adjustedModels = data.map(model => ({
          ...model,
          file: isLowSpecDevice && model.alt ? model.alt : model.file,
        }));
        setModels(adjustedModels);
        setSelectedModel(adjustedModels[0]?.file);
      })
      .catch(console.error);
  }, []);

  return (
    <div className="container">
      <div className="sidebar">
        <h3>Select a Model</h3>
        <ul>
          {models.map((model) => (
            <li
              key={model.file}
              className={selectedModel === model.file ? 'selected' : ''}
              onClick={() => setSelectedModel(model.file)}
            >
              {model.name}
            </li>
          ))}
        </ul>
      </div>

      <div className="canvas-container">
        <Canvas camera={{ position: [2.5, 2.5, 2.5], fov: 45 }}>
          <ambientLight intensity={0.5} />
          <ModelLoader modelPath={`./stls/${selectedModel}`} />
          <OrbitControls />
        </Canvas>
      </div>
    </div>
  );
};

export default App;
